// ── Lookup helpers ──────────────────────────────────────────
function getRoutesByRegion(region) {
    return italianRoutesDB.filter(r => r.region === region);
}
function getRouteById(id) {
    return italianRoutesDB.find(r => r.id === id) || null;
}
function isVeniceIslandHotel(hotelName) {
    const h = (hotelName || '').toLowerCase();
    return VENICE_ISLAND_HOTELS.some(vh => vh.toLowerCase().includes(h) || h.includes(vh.toLowerCase()));
}